mapper.insert:
INSERT INTO family (
user_id, family_name, relation, birth_date, family_img
) VALUES (
#{userId}, #{familyName}, #{relation}, #{birthDate}, #{familyImg}
)

mapper.update:
UPDATE family
SET family_name = #{familyName},
relation = #{relation},
birth_date = #{birthDate},
family_img = #{familyImg}
WHERE family_id = #{familyId}
AND user_id = #{userId}

mapper.delete:
